package com.bookeat.admin.service;
import com.bookeat.admin.dto.AdminRequests;import com.bookeat.user.entity.*;import com.bookeat.user.repository.*;import com.bookeat.user.mapper.UserMapper;import com.bookeat.user.response.UserResponse;import com.bookeat.common.response.PageResponse;import com.bookeat.common.audit.AuditService;import com.bookeat.commerce.service.CommerceAccess;import com.bookeat.exception.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.data.domain.*;import lombok.RequiredArgsConstructor;import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class AdminUserService {
 private final UserRepository users;private final RoleRepository roles;private final UserMapper mapper;private final PasswordEncoder passwords;private final AuditService audit;private final JdbcTemplate jdbc;private final CommerceAccess access;
 public record View(long version,UserResponse user){}
 public static final Set<RoleCode> ADMINS=Set.of(RoleCode.ADMIN,RoleCode.SUPER_ADMIN,RoleCode.OPERATIONS_ADMIN,RoleCode.FINANCE_ADMIN,RoleCode.SUPPORT_ADMIN,RoleCode.RESTAURANT_VERIFICATION_ADMIN,RoleCode.CONTENT_ADMIN);
 @Transactional(readOnly=true) public PageResponse<View> list(int page,int size){return PageResponse.from(users.findDistinctByRoles_CodeIn(ADMINS,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt","id"))).map(u->new View(u.getVersion(),mapper.toResponse(u))));}
 @Transactional(readOnly=true) public View get(UUID id){var u=users.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));return new View(u.getVersion(),mapper.toResponse(u));}
 public View status(UUID actor,UUID id,AdminRequests.Action q,UserStatus state,boolean superAdmin){lockAdministration();if(actor.equals(id))throw new ApiException(ErrorCode.ACCESS_DENIED);var u=users.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));if(u.getRoles().stream().anyMatch(r->ADMINS.contains(r.getCode()))&&!superAdmin)throw new ApiException(ErrorCode.ACCESS_DENIED);access.version(u.getVersion(),q.version());protectLast(u,state,u.getRoles());u.setStatus(state);u.setTokenVersion(u.getTokenVersion()+1);users.flush();audit.recordReason(actor,"USER_"+state,"User",id,q.reason());return new View(u.getVersion(),mapper.toResponse(u));}
 public View create(UUID actor,AdminRequests.Create q){lockAdministration();if(!ADMINS.containsAll(q.roles()))throw new ApiException(ErrorCode.ACCESS_DENIED);var u=new User();u.setFirstName(q.firstName());u.setLastName(q.lastName());u.setEmail(q.email().trim().toLowerCase(Locale.ROOT));u.setPasswordHash(passwords.encode(q.password()));u.setRoles(resolve(q.roles()));u.setStatus(UserStatus.ACTIVE);users.saveAndFlush(u);audit.record(actor,"ADMIN_USER_CREATED","User",u.getId(),null);return new View(u.getVersion(),mapper.toResponse(u));}
 public View roles(UUID actor,UUID id,AdminRequests.Roles q){lockAdministration();var administrator=users.findById(actor).orElseThrow(()->new ApiException(ErrorCode.AUTH_TOKEN_INVALID));if(actor.equals(id)||administrator.getRoles().stream().noneMatch(r->r.getCode()==RoleCode.SUPER_ADMIN||r.getCode()==RoleCode.ADMIN)||!ADMINS.containsAll(q.roles()))throw new ApiException(ErrorCode.ACCESS_DENIED);var u=users.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));if(u.getRoles().stream().anyMatch(r->!ADMINS.contains(r.getCode())))throw new ApiException(ErrorCode.ACCESS_DENIED);access.version(u.getVersion(),q.version());var next=resolve(q.roles());protectLast(u,u.getStatus(),next);u.setRoles(next);u.setTokenVersion(u.getTokenVersion()+1);users.flush();audit.recordReason(actor,"ADMIN_ROLES_CHANGED","User",id,q.reason());return new View(u.getVersion(),mapper.toResponse(u));}
 @Transactional(readOnly=true) public List<Map<String,Object>> roles(){return roles.findAll().stream().map(r->Map.<String,Object>of("id",r.getId(),"code",r.getCode(),"description",r.getDescription(),"permissions",r.getPermissions().stream().map(Permission::getCode).sorted().toList())).toList();}
 @Transactional(readOnly=true) public List<Map<String,Object>> permissions(){return jdbc.queryForList("select code,description from permissions order by code");}
 private Set<Role> resolve(Set<RoleCode> codes){var selected=new HashSet<Role>();for(var code:codes)selected.add(roles.findByCode(code).orElseThrow(()->new ApiException(ErrorCode.VALIDATION_FAILED)));return selected;}
 private void protectLast(User before,UserStatus state,Set<Role> roles){if(before.getStatus()==UserStatus.ACTIVE&&before.getRoles().stream().anyMatch(r->r.getCode()==RoleCode.SUPER_ADMIN)&&(state!=UserStatus.ACTIVE||roles.stream().noneMatch(r->r.getCode()==RoleCode.SUPER_ADMIN))){Integer n=jdbc.queryForObject("select count(*) from users u join user_roles ur on ur.user_id=u.id join roles r on r.id=ur.role_id where u.status='ACTIVE' and r.code='SUPER_ADMIN'",Integer.class);if(n==null||n<=1)throw new ApiException(ErrorCode.ACCESS_DENIED);}}
 private void lockAdministration(){jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>) c->{try(var s=c.prepareStatement("select pg_advisory_xact_lock(91415001)")){s.execute();}return null;});}
}
